import { useState, useEffect, useCallback } from 'react';
import { storage } from './storage';
import {
    mockDashboardData,
    mockSales,
    mockProducts,
    mockSuppliers,
    mockFinance,
    mockPurchases,
    mockAlerts
} from '@/lib/mockData';

export function useData<T>(url: string) {
    const [data, setData] = useState<T | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const fetchData = useCallback(() => {
        let key = '';
        let defaultData: any = [];

        if (url.includes('products')) {
            key = 'products';
            defaultData = mockProducts;
        } else if (url.includes('sales')) {
            key = 'sales';
            defaultData = mockSales;
        } else if (url.includes('suppliers')) {
            key = 'suppliers';
            defaultData = mockSuppliers;
        } else if (url.includes('finance') || url.includes('reports')) {
            key = 'finance';
            defaultData = mockFinance;
        } else if (url.includes('purchases')) {
            key = 'purchases';
            defaultData = mockPurchases;
        } else if (url.includes('alerts')) {
            key = 'alerts';
            defaultData = mockAlerts;
        } else if (url.includes('dashboard')) {
            key = 'dashboard';
            defaultData = mockDashboardData;
        } else if (url.includes('invoices')) {
            key = 'sales';
            defaultData = mockSales;
        } else if (url.includes('batches')) {
            key = 'batches';
            defaultData = [];
        }

        const storedData = key ? storage.get(key, defaultData) : defaultData;
        setData(storedData);
        setLoading(false);
    }, [url]);

    useEffect(() => {
        fetchData();

        // Listen for storage changes to sync data across components
        window.addEventListener('jailwatch_storage_change', fetchData);
        return () => window.removeEventListener('jailwatch_storage_change', fetchData);
    }, [fetchData]);

    return { data, loading, error, refetch: fetchData };
}
